"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[76473],{14128:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"RagdollCmdrService","desc":"Ragdoll admin commands.\\n\\n| Command | What it does |\\n| --- | --- |\\n| `ragdoll` | Ragdolls players |\\n| `unragdoll` | Takes players out of a ragdoll |\\n\\nBoth take a list of players, so `ragdoll *` reaches everyone in the server as readily as a single\\nusername does, and both act on the humanoid of each player\'s current character. A player without\\none is reported and skipped, so one dead or loading player never hides what happened to the rest.","realm":["Server"],"source":{"line":17,"path":"src/ragdoll/src/Server/Cmdr/RagdollCmdrService.lua"}}')}}]);